package com.crestlinebank.ui;
import com.crestlinebank.dao.StaffDao;import com.crestlinebank.model.Staff;
import javax.swing.*;import javax.swing.table.*;import java.awt.*;import java.math.BigDecimal;
public class StaffFrame extends JFrame {
 private final Staff staff; private final StaffDao dao=new StaffDao(); private final DefaultTableModel model=new DefaultTableModel(new String[]{"Loan ID","Customer","Amount","Status"},0){public boolean isCellEditable(int r,int c){return false;}}; private final DefaultTableModel tasks=new DefaultTableModel(new String[]{"Task ID","Task","Details","Status","Assigned"},0){public boolean isCellEditable(int r,int c){return false;}};
 public StaffFrame(Staff s){staff=s;setTitle("Crestline Bank | Staff Portal");setSize(900,600);setMinimumSize(new Dimension(720,480));setLocationRelativeTo(null);build();load();}
 private void build(){JPanel root=new JPanel(new BorderLayout(14,14));root.setBorder(BorderFactory.createEmptyBorder(22,24,22,24));root.setBackground(Theme.BACKGROUND);JLabel h=new JLabel("Welcome, "+staff.fullName()+"  ·  "+staff.role().replace('_',' '));h.setFont(Theme.font(Font.BOLD,22));h.setForeground(Theme.NAVY);JLabel limit=new JLabel("Your loan approval authority: ₹"+staff.maxLoanApproval()+"   |   Assigned work is limited by your role.");limit.setForeground(Theme.MUTED);JPanel north=new JPanel(new GridLayout(2,1,0,6));north.setOpaque(false);north.add(h);north.add(limit);root.add(north,BorderLayout.NORTH);JTable t=new JTable(model);t.setRowHeight(30);JTable taskTable=new JTable(tasks);taskTable.setRowHeight(28);JTabbedPane tabs=new JTabbedPane();tabs.addTab("Loan applications",new JScrollPane(t));tabs.addTab("My assigned tasks",new JScrollPane(taskTable));root.add(tabs,BorderLayout.CENTER);JPanel bar=new JPanel(new FlowLayout(FlowLayout.LEFT));bar.setOpaque(false);JButton approve=Ui.button("Approve selected loan",Theme.GREEN),reject=Ui.button("Reject selected loan",Theme.RED),complete=Ui.button("Complete selected task",Theme.GREEN),refresh=Ui.button("Refresh",Theme.GOLD),logout=Ui.button("Sign out",Theme.NAVY);boolean canDecide=staff.role().equals("LOAN_OFFICER")||staff.role().equals("BRANCH_MANAGER");approve.setEnabled(canDecide);reject.setEnabled(canDecide);approve.setToolTipText(canDecide?"Approve within your limit":"Your role cannot decide loan applications");reject.setToolTipText(canDecide?"Reject pending loans":"Your role cannot decide loan applications");approve.addActionListener(e->decide(t,"APPROVED"));reject.addActionListener(e->decide(t,"REJECTED"));complete.addActionListener(e->complete(taskTable));refresh.addActionListener(e->load());logout.addActionListener(e->{new LoginFrame().setVisible(true);dispose();});bar.add(approve);bar.add(reject);bar.add(complete);bar.add(refresh);bar.add(logout);root.add(bar,BorderLayout.SOUTH);setContentPane(root);}
 private void load(){try{model.setRowCount(0);for(Object[] r:dao.pendingLoans())model.addRow(r);tasks.setRowCount(0);for(Object[] r:dao.tasks(staff.id()))tasks.addRow(r);}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Load failed",0);}}
 private void complete(JTable t){int r=t.getSelectedRow();if(r<0){JOptionPane.showMessageDialog(this,"Select a task first.");return;}long id=((Number)tasks.getValueAt(t.convertRowIndexToModel(r),0)).longValue();try{dao.completeTask(staff.id(),id);load();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Task update failed",JOptionPane.ERROR_MESSAGE);}}
 private void decide(JTable t,String status){int row=t.getSelectedRow();if(row<0){JOptionPane.showMessageDialog(this,"Select a pending loan first.");return;}int id=((Number)model.getValueAt(t.convertRowIndexToModel(row),0)).intValue();BigDecimal amount=new BigDecimal(model.getValueAt(t.convertRowIndexToModel(row),2).toString());if("APPROVED".equals(status)&&amount.compareTo(staff.maxLoanApproval())>0){JOptionPane.showMessageDialog(this,"This loan exceeds your approval limit. Please forward it to the Admin.","Approval limit",JOptionPane.WARNING_MESSAGE);return;}if(JOptionPane.showConfirmDialog(this,status+" loan #"+id+"?","Confirm",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;try{dao.decideLoan(staff.id(),id,status);load();}catch(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Action failed",JOptionPane.ERROR_MESSAGE);}}
}
